def backup_database():
    """Создает бэкап базы данных и возвращает zip-архив"""
    try:
        # Создаем zip в памяти
        zip_buffer = io.BytesIO()

        with zipfile.ZipFile(zip_buffer, 'w') as zipf:
            # Добавляем базу данных в архив
            if os.path.exists('production.db'):
                zipf.write('production.db', 'production.db')
            else:
                st.error("Файл базы данных production.db не найден")
                return None

        zip_data = zip_buffer.getvalue()
        zip_buffer.close()

        return zip_data
    except Exception as e:
        st.error(f"Ошибка при создании бэкапа: {str(e)}")
        return None


def restore_database(uploaded_file):
    """Восстанавливает базу данных из загруженного zip архива"""
    try:
        # Создаем временную директорию для распаковки
        with tempfile.TemporaryDirectory() as temp_dir:
            # Сохраняем загруженный файл
            zip_path = os.path.join(temp_dir, 'backup.zip')
            with open(zip_path, 'wb') as f:
                f.write(uploaded_file.getbuffer())

            # Распаковываем архив
            with zipfile.ZipFile(zip_path, 'r') as zipf:
                zipf.extractall(temp_dir)

            # Проверяем наличие файла базы данных
            db_path = os.path.join(temp_dir, 'production.db')
            if not os.path.exists(db_path):
                st.error("В архиве не найден файл production.db")
                return False

            # Закрываем текущее соединение с БД
            if 'conn' in st.session_state:
                st.session_state.conn.close()

            # Заменяем текущую базу данных
            shutil.copy(db_path, 'production.db')

            # Пересоздаем соединение
            st.session_state.conn = init_db()

            return True

    except Exception as e:
        st.error(f"Ошибка при восстановлении бэкапа: {str(e)}")
        return False


# Инициализация базы данных
def init_db():
    conn = sqlite3.connect('production.db', check_same_thread=False)
    cursor = conn.cursor()

    # Типы оборудования
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS equipment_types (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            sort_order INTEGER NOT NULL UNIQUE,
            color TEXT NOT NULL
        )
    ''')

    # Оборудование
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS equipment (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            sort_order INTEGER NOT NULL UNIQUE,
            show_on_chart BOOLEAN NOT NULL DEFAULT 1,
            type_id INTEGER NOT NULL,
            FOREIGN KEY (type_id) REFERENCES equipment_types (id)
        )
    ''')

    # Заказы
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            color TEXT NOT NULL,
            quantity INTEGER NOT NULL,
            priority_order INTEGER NOT NULL DEFAULT 0
        )
    ''')

    # Календарь
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS calendar (
            date TEXT PRIMARY KEY,
            work_hours INTEGER NOT NULL CHECK (work_hours IN (0, 8, 12, 24))
        )
    ''')

    # Работы
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS jobs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_id INTEGER NOT NULL,
            equipment_id INTEGER NOT NULL,
            duration_hours REAL NOT NULL,
            hour_offset REAL NOT NULL DEFAULT 0,
            start_date TEXT,
            status TEXT NOT NULL CHECK (status IN ('planned', 'started', 'completed')),
            is_locked BOOLEAN NOT NULL DEFAULT 0,
            FOREIGN KEY (order_id) REFERENCES orders (id),
            FOREIGN KEY (equipment_id) REFERENCES equipment (id)
        )
    ''')

    # Таблица для хранения настроек системы
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS system_settings (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            view_mode TEXT NOT NULL DEFAULT 'week',
            pixels_per_hour INTEGER NOT NULL DEFAULT 20,
            row_height INTEGER NOT NULL DEFAULT 70,
            job_height_ratio INTEGER NOT NULL DEFAULT 80,
            chart_start_date TEXT NOT NULL DEFAULT '2024-01-01'
        )
    ''')

    # Инициализируем настройки по умолчанию если записи нет
    cursor.execute('SELECT COUNT(*) FROM system_settings')
    count = cursor.fetchone()[0]
    if count == 0:
        cursor.execute('''
            INSERT INTO system_settings (id, view_mode, pixels_per_hour, 
                                       row_height, job_height_ratio, chart_start_date)
            VALUES (1, 'week', 20, 70, 80, ?)
        ''', (datetime.now().date().isoformat(),))

    conn.commit()
    return conn


def export_to_excel(conn, jobs_df, equipment_df, start_date, end_date, calendar_dict):
    """Экспорт диаграммы Ганта в Excel файл"""

    # Создаем новую книгу Excel
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "График загрузки оборудования"

    # Стили границ
    thin_border = Border(
        left=Side(style='thin'),
        right=Side(style='thin'),
        top=Side(style='thin'),
        bottom=Side(style='thin')
    )

    thick_border = Border(
        left=Side(style='thick'),
        right=Side(style='thick'),
        top=Side(style='thick'),
        bottom=Side(style='thick')
    )

    # Стили выравнивания
    center_align = Alignment(horizontal='center', vertical='center', wrap_text=True)

    # Рассчитываем общее количество столбцов (1 столбец = 0.25 часа)
    total_columns = 0
    day_columns = {}  # Словарь для хранения информации о днях

    current_date = start_date
    while current_date <= end_date:
        work_hours = calendar_dict.get(current_date.isoformat(), 8)
        is_weekend = (work_hours == 0)
        # Для выходных используем 2 часа (8 столбцов), для рабочих - обычные рабочие часы
        day_columns_count = work_hours * 4 if not is_weekend else 2 * 4  # 2 часа для выходных

        day_columns[current_date] = {
            'start_col': total_columns + 1,
            'end_col': total_columns + day_columns_count,
            'work_hours': work_hours,
            'is_weekend': is_weekend,
            'hours_count': 2 if is_weekend else work_hours  # Количество часов для отображения
        }

        total_columns += day_columns_count
        current_date += timedelta(days=1)

    # Настройка столбцов
    # Первый столбец для названий оборудования
    ws.column_dimensions['A'].width = 25

    # Столбцы для временной шкалы (ширина 1)
    for col in range(2, total_columns + 2):
        ws.column_dimensions[get_column_letter(col)].width = 1

    # ШАПКА ТАБЛИЦЫ - даты
    header_row = 1
    for date, day_info in day_columns.items():
        start_col = day_info['start_col'] + 1  # +1 потому что первый столбец A
        end_col = day_info['end_col'] + 1

        if start_col <= end_col:
            # Объединяем ячейки для дня
            start_letter = get_column_letter(start_col)
            end_letter = get_column_letter(end_col)
            ws.merge_cells(f'{start_letter}{header_row}:{end_letter}{header_row}')

            # Заполняем дату
            cell = ws[f'{start_letter}{header_row}']
            cell.value = f"{date.strftime('%d.%m')} ({day_info['work_hours']})"
            cell.alignment = center_align
            cell.font = Font(bold=True)
            cell.border = thick_border  # Толстые границы для ячейки с датой

            # Заливка для выходных
            if day_info['is_weekend']:
                cell.fill = PatternFill(start_color='D3D3D3', end_color='D3D3D3', fill_type='solid')

    # СТРОКИ ОБОРУДОВАНИЯ
    current_row = 2

    for _, equipment in equipment_df.iterrows():
        # Получаем работы для этого оборудования
        equipment_jobs = jobs_df[jobs_df['equipment_name'] == equipment['name']]

        # Рассчитываем общее время работы оборудования в диапазоне
        total_work_hours = 0
        for _, job in equipment_jobs.iterrows():
            hour_offset = float(job['hour_offset']) if not pd.isna(job['hour_offset']) else 0.0
            duration_hours = float(job['duration_hours'])
            start_dt = pd.to_datetime(job['start_date'])

            # Рассчитываем расписание работы
            finish_date_str, daily_schedule = calculate_finish_date(
                conn, start_dt.isoformat(), duration_hours, hour_offset, job['id']
            )

            # ДОБАВЛЯЕМ ВЫХОДНЫЕ ДНИ В РАСПИСАНИЕ
            extended_schedule = []
            work_start_date = pd.to_datetime(job['start_date']).date()
            work_finish_date = pd.to_datetime(finish_date_str).date()

            current_schedule_date = work_start_date
            schedule_index = 0

            while current_schedule_date <= work_finish_date:
                current_date_str = current_schedule_date.isoformat()

                # Проверяем, есть ли этот день в оригинальном расписании
                if schedule_index < len(daily_schedule) and daily_schedule[schedule_index][0] == current_date_str:
                    # День есть в расписании - добавляем как есть
                    extended_schedule.append(daily_schedule[schedule_index])
                    schedule_index += 1
                else:
                    # Дня нет в расписании - проверяем является ли он выходным
                    work_hours = calendar_dict.get(current_date_str, 8)
                    if work_hours == 0:  # Выходной день
                        extended_schedule.append((current_date_str, 0, 0))  # hours=0, offset=0
                    # else: рабочий день без работы - не добавляем

                current_schedule_date += timedelta(days=1)

            # Используем расширенное расписание с выходными
            daily_schedule_with_weekends = extended_schedule

            # Суммируем часы в диапазоне дат
            for day_str, hours, offset in daily_schedule_with_weekends:
                day_date = pd.to_datetime(day_str).date()
                if start_date <= day_date <= end_date:
                    total_work_hours += hours

        # Три строки для одного оборудования
        for i in range(3):
            row_height = 8 if i in [0, 2] else 35  # Тонкие строки сверху и снизу, толстая посередине
            ws.row_dimensions[current_row + i].height = row_height

            # Ячейка с названием оборудования (объединенная для трех строк)
            if i == 0:
                ws.merge_cells(f'A{current_row}:A{current_row + 2}')
                equipment_cell = ws[f'A{current_row}']
                equipment_cell.value = f"{equipment['name']}\n({total_work_hours:.1f}ч)"
                equipment_cell.alignment = center_align
                equipment_cell.font = Font(bold=True)
                equipment_cell.border = thick_border

        # ПОДГОТОВКА ДАННЫХ ДЛЯ ОТОБРАЖЕНИЯ РАБОТ
        # Создаем карту занятости для средней строки
        middle_row_occupancy = {}  # key: (start_col, end_col), value: job_data

        for _, job in equipment_jobs.iterrows():
            hour_offset = float(job['hour_offset']) if not pd.isna(job['hour_offset']) else 0.0
            duration_hours = float(job['duration_hours'])
            start_dt = pd.to_datetime(job['start_date'])

            # Рассчитываем расписание работы
            finish_date_str, daily_schedule = calculate_finish_date(
                conn, start_dt.isoformat(), duration_hours, hour_offset, job['id']
            )

            # ДОБАВЛЯЕМ ВЫХОДНЫЕ ДНИ В РАСПИСАНИЕ (ТО ЖЕ САМОЕ ДЛЯ ОТОБРАЖЕНИЯ)
            extended_schedule = []
            work_start_date = pd.to_datetime(job['start_date']).date()
            work_finish_date = pd.to_datetime(finish_date_str).date()

            current_schedule_date = work_start_date
            schedule_index = 0

            while current_schedule_date <= work_finish_date:
                current_date_str = current_schedule_date.isoformat()

                if schedule_index < len(daily_schedule) and daily_schedule[schedule_index][0] == current_date_str:
                    extended_schedule.append(daily_schedule[schedule_index])
                    schedule_index += 1
                else:
                    work_hours = calendar_dict.get(current_date_str, 8)
                    if work_hours == 0:  # Выходной день
                        extended_schedule.append((current_date_str, 0, 0))

                current_schedule_date += timedelta(days=1)

            daily_schedule_with_weekends = extended_schedule

            # Для каждого дня в расширенном расписании
            for day_str, hours, offset in daily_schedule_with_weekends:
                day_date = pd.to_datetime(day_str).date()

                # Проверяем, попадает ли день в диапазон экспорта
                if day_date in day_columns:
                    day_info = day_columns[day_date]

                    # Для выходных дней (hours=0) создаем запись на весь день
                    if hours == 0 and day_info['is_weekend']:
                        start_col = day_info['start_col'] + 1
                        end_col = day_info['end_col'] + 1

                        middle_row_occupancy[(start_col, end_col)] = {
                            'job': job,
                            'day_info': day_info,
                            'is_weekend': True
                        }

                    # Для рабочих дней с работой
                    elif hours > 0:
                        # Рассчитываем столбцы для работы в этот день
                        start_hour_offset = offset
                        end_hour_offset = offset + hours

                        # Для выходных дней ограничиваем 2 часами
                        if day_info['is_weekend']:
                            max_hours = 2
                        else:
                            max_hours = day_info['work_hours']

                        # Ограничиваем рабочими часами дня
                        end_hour_offset = min(end_hour_offset, max_hours)

                        if start_hour_offset < end_hour_offset:
                            # Переводим часы в столбцы (1 столбец = 0.25 часа)
                            start_col_offset = int(start_hour_offset * 4)
                            end_col_offset = int(end_hour_offset * 4)

                            start_col = day_info['start_col'] + 1 + start_col_offset
                            end_col = day_info['start_col'] + 1 + end_col_offset - 1

                            if start_col <= end_col:
                                middle_row_occupancy[(start_col, end_col)] = {
                                    'job': job,
                                    'day_info': day_info,
                                    'is_weekend': False
                                }

        # ЗАПОЛНЕНИЕ ВРЕМЕННОЙ ШКАЛЫ ДЛЯ ОБОРУДОВАНИЯ
        for date, day_info in day_columns.items():
            start_col = day_info['start_col'] + 1
            end_col = day_info['end_col'] + 1

            # СТРОКА 1 и 3 (верхняя и нижняя) - объединяем по часам
            for row_offset in [0, 2]:  # Строки 1 и 3
                row = current_row + row_offset

                # Объединяем кванты в часы (4 кванта = 1 час)
                hours_in_day = day_info['hours_count']

                for hour in range(hours_in_day):
                    hour_start_col = start_col + (hour * 4)
                    hour_end_col = hour_start_col + 3  # 4 кванта на час

                    if hour_start_col <= hour_end_col:
                        # Объединяем 4 кванта в одну ячейку часа
                        start_letter = get_column_letter(hour_start_col)
                        end_letter = get_column_letter(hour_end_col)
                        ws.merge_cells(f'{start_letter}{row}:{end_letter}{row}')

                        # Обращаемся к ПЕРВОЙ ячейке объединенного диапазона
                        hour_cell = ws[f'{start_letter}{row}']

                        # Применяем границы ко всей объединенной ячейке (только вертикальные)
                        _apply_vertical_borders_only(hour_cell, hour_start_col, hour_end_col, start_col, end_col,
                                                     day_info)

                        # Заливка для выходных
                        if day_info['is_weekend']:
                            hour_cell.fill = PatternFill(start_color='F0F0F0', end_color='F0F0F0', fill_type='solid')

            # СТРОКА 2 (средняя) - сначала рисуем сетку часов, потом объединяем работы
            middle_row = current_row + 1

            # НАХОДИМ ВСЕ РАБОТЫ В ЭТОМ ДНЕ ДЛЯ СРЕДНЕГО РЯДА
            day_jobs = []
            for (job_start, job_end), job_data in middle_row_occupancy.items():
                if job_start >= start_col and job_end <= end_col:
                    day_jobs.append((job_start, job_end, job_data))

            # Сортируем работы по начальной колонке
            day_jobs.sort(key=lambda x: x[0])

            # Сначала создаем сетку часов во второй строке (как в 1 и 3 строках, но без объединения)
            hours_in_day = day_info['hours_count']
            for hour in range(hours_in_day):
                hour_start_col = start_col + (hour * 4)
                hour_end_col = hour_start_col + 3  # 4 кванта на час

                # Применяем границы к каждому кванту в часе
                for col in range(hour_start_col, hour_end_col + 1):
                    cell = ws[f'{get_column_letter(col)}{middle_row}']

                    # Границы для квантов (только вертикальные)
                    border_parts = {}

                    # Левая граница - толстая если это первый квант часа и первый час дня
                    if col == hour_start_col and hour == 0:
                        border_parts['left'] = Side(style='thick')
                    elif col == hour_start_col:
                        border_parts['left'] = Side(style='thin')
                    else:
                        border_parts['left'] = Side(style=None)

                    # Правая граница - толстая если это последний квант часа и последний час дня
                    if col == hour_end_col and hour == hours_in_day - 1:
                        border_parts['right'] = Side(style='thick')
                    elif col == hour_end_col:
                        border_parts['right'] = Side(style='thin')
                    else:
                        border_parts['right'] = Side(style=None)

                    # Верхняя и нижняя границы - убираем
                    border_parts['top'] = Side(style=None)
                    border_parts['bottom'] = Side(style=None)

                    cell.border = Border(**border_parts)

            # ОБРАБОТКА ВЫХОДНЫХ И РАБОЧИХ ДНЕЙ
            if day_info['is_weekend']:
                # Для выходных дней - создаем объединенную ячейку на весь день
                start_letter = get_column_letter(start_col)
                end_letter = get_column_letter(end_col)
                merge_range = f'{start_letter}{middle_row}:{end_letter}{middle_row}'
                ws.merge_cells(merge_range)

                weekend_cell = ws[f'{start_letter}{middle_row}']

                # Ищем работу, которая включает этот выходной день
                weekend_job = None
                for job_start, job_end, job_data in day_jobs:
                    if job_data.get('is_weekend', False):
                        weekend_job = job_data
                        break

                if weekend_job:
                    # Есть работа в этот выходной - используем приглушенный цвет заказа

                    dark_color = darken_color(hex_to_rgb(weekend_job['job']['order_color']), 0.3)
                    fill_color_hex = rgb_to_hex(dark_color).strip("#")

                    # job_text = weekend_job['job']['order_name']
                    # if len(job_text) > 15:
                    #     job_text = job_text[:15] + '...'
                    # weekend_cell.value = job_text
                    # weekend_cell.alignment = center_align
                    # weekend_cell.font = Font(size=8, bold=True, color='FFFFFF')
                else:
                    # Нет работ - серая заливка
                    fill_color_hex = 'F0F0F0'

                weekend_cell.fill = PatternFill(start_color=fill_color_hex, end_color=fill_color_hex, fill_type='solid')
                _apply_vertical_borders_only(weekend_cell, start_col, end_col, start_col, end_col, day_info)

            else:
                # Для рабочих дней - создаем отдельные ячейки для работ
                for job_start, job_end, job_data in day_jobs:
                    if not job_data.get('is_weekend', False) and job_start <= job_end:  # Только рабочие дни
                        start_letter = get_column_letter(job_start)
                        end_letter = get_column_letter(job_end)

                        merge_range = f'{start_letter}{middle_row}:{end_letter}{middle_row}'
                        ws.merge_cells(merge_range)

                        job_cell = ws[f'{start_letter}{middle_row}']

                        job_text = job_data['job']['order_name']
                        if len(job_text) > 15:
                            job_text = job_text[:15] + '...'

                        try:
                            job_cell.value = job_text
                            job_cell.alignment = center_align
                            job_cell.font = Font(size=8, bold=True)
                        except Exception as e:
                            pass

                        color_hex = job_data['job']['order_color'].lstrip('#')
                        job_cell.fill = PatternFill(
                            start_color=color_hex,
                            end_color=color_hex,
                            fill_type='solid'
                        )

                        if color_hex in ['FFFFFF', 'FFFF00', '00FFFF']:
                            job_cell.font = Font(size=8, bold=True, color='000000')
                        else:
                            job_cell.font = Font(size=8, bold=True, color='FFFFFF')

                        _apply_vertical_borders_only(job_cell, job_start, job_end, start_col, end_col, day_info)

        current_row += 3

    # ОБВОДИМ ВСЮ ОБЛАСТЬ ДИАГРАММЫ ТОЛСТЫМИ ВНЕШНИМИ ГРАНИЦАМИ
    _apply_outer_thick_borders(ws, total_columns, 1, current_row - 1)

    for i, equipment in equipment_df.iterrows():
        _apply_outer_thick_borders(ws, total_columns, 2 + i * 3, 5 + i * 3 - 1)

    # Сохраняем файл в буфер
    excel_buffer = io.BytesIO()
    wb.save(excel_buffer)
    excel_buffer.seek(0)

    return excel_buffer


def _apply_vertical_borders_only(cell, cell_start_col, cell_end_col, day_start_col, day_end_col, day_info):
    """Применяет только вертикальные границы к ячейке (без горизонтальных)"""
    border_parts = {}

    # Левая граница - толстая только если это первая ячейка дня
    if cell_start_col == day_start_col:
        border_parts['left'] = Side(style='thick')
    else:
        border_parts['left'] = Side(style='thin')

    # Правая граница - толстая только если это последняя ячейка дня
    if cell_end_col == day_end_col:
        border_parts['right'] = Side(style='thick')
    else:
        border_parts['right'] = Side(style='thin')

    # Верхняя и нижняя границы - убираем (нет границ)
    border_parts['top'] = Side(style=None)
    border_parts['bottom'] = Side(style=None)

    cell.border = Border(**border_parts)


def _apply_outer_thick_borders(ws, total_columns, first_row, last_row):
    """Применяет толстые внешние границы ко всей области диаграммы"""

    # Верхняя граница (шапка с датами)
    for col in range(1, total_columns + 2):
        col_letter = get_column_letter(col)
        cell = ws[f'{col_letter}{first_row}']
        current_border = cell.border
        new_border = Border(
            left=current_border.left,
            right=current_border.right,
            top=Side(style='thick'),  # Толстая верхняя граница
            bottom=current_border.bottom
        )
        cell.border = new_border

    # Нижняя граница
    for col in range(1, total_columns + 2):
        col_letter = get_column_letter(col)
        cell = ws[f'{col_letter}{last_row}']
        current_border = cell.border
        new_border = Border(
            left=current_border.left,
            right=current_border.right,
            top=current_border.top,
            bottom=Side(style='thick')  # Толстая нижняя граница
        )
        cell.border = new_border

    # Левая граница (столбец A)
    for row in range(1, last_row + 1):
        cell = ws[f'A{row}']
        current_border = cell.border
        new_border = Border(
            left=Side(style='thick'),  # Толстая левая граница
            right=current_border.right,
            top=current_border.top,
            bottom=current_border.bottom
        )
        cell.border = new_border

    # Правая граница (последний столбец)
    last_col_letter = get_column_letter(total_columns + 1)
    for row in range(1, last_row + 1):
        cell = ws[f'{last_col_letter}{row}']
        current_border = cell.border
        new_border = Border(
            left=current_border.left,
            right=Side(style='thick'),  # Толстая правая граница
            top=current_border.top,
            bottom=current_border.bottom
        )
        cell.border = new_border


def load_system_settings(conn):
    """Загружает настройки системы из БД"""
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM system_settings WHERE id = 1')
    result = cursor.fetchone()

    if result:
        return {
            'view_mode': result[1],
            'pixels_per_hour': result[2],
            'row_height': result[3],
            'job_height_ratio': result[4],
            'chart_start_date': datetime.fromisoformat(result[5]).date()
        }
    return None


def save_system_settings(conn, settings):
    """Сохраняет настройки системы в БД"""
    st.write(settings)
    cursor = conn.cursor()
    cursor.execute('''
        UPDATE system_settings SET 
            view_mode = ?,
            pixels_per_hour = ?,
            row_height = ?,
            job_height_ratio = ?,
            chart_start_date = ?
        WHERE id = 1
    ''', (
        settings['view_mode'],
        settings['pixels_per_hour'],
        settings['row_height'],
        settings['job_height_ratio'],
        settings['chart_start_date'].isoformat()
    ))
    conn.commit()


def adjust_schedule_and_fix_conflicts(conn, start_date: str, offset: float, duration: float,
                                      equipment_id: int, job_id: Optional[int] = None,
                                      only_check: bool = True) -> bool:
    """
    Корректирует расписание и устраняет конфликты, перепланируя последующие работы.

    Args:
        conn: соединение с БД
        start_date: исходная дата начала в формате ISO
        offset: смещение от начала дня в часах
        duration: длительность работы в часах
        equipment_id: ID оборудования
        job_id: ID текущей работы (опционально)

     Returns:
        bool: True если есть конфликты, False если конфликтов нет
    """
    cursor = conn.cursor()

    # 1. Проверяем конфликты и получаем доступную дату
    available_date, available_offset = check_equipment_conflicts(
        conn, equipment_id, job_id, start_date, offset, duration
    )

    # 2. Если дата и смещение совпадают с исходными - нет конфликтов
    if available_date == start_date and abs(available_offset - offset) < 0.01:
        return False

    if not only_check:
        # 3. Вычисляем финишные параметры для исходной работы
        finish_date, daily_schedule = calculate_finish_date(
            conn, start_date, duration, offset, job_id
        )

        # Получаем время окончания из последнего дня расписания
        if daily_schedule:
            last_day_date, last_day_hours, last_day_offset = daily_schedule[-1]
            finish_offset = last_day_offset + last_day_hours
            if abs(finish_offset - last_day_hours) < 0.1:
                finish_offset = 0
                finish_date = (datetime.fromisoformat(finish_date) + timedelta(days=1)).date().isoformat()
        else:
            finish_offset = 0

        # 4. Вычисляем next_start_date как finish_date + finish_offset + 0.25 часа
        finish_dt = datetime.fromisoformat(finish_date)
        next_start_dt = finish_dt + timedelta(hours=finish_offset + 0.25 if finish_offset != 0 else finish_offset)
        next_start_date = next_start_dt.date().isoformat()
        next_start_offset = next_start_dt.hour + next_start_dt.minute / 60.0

        # 5. Получаем список будущих работ, исключая текущую
        future_jobs = get_future_jobs_excluding_current_optimized(
            conn, start_date, offset, job_id, equipment_id
        )

        # 6. Перебираем работы и перепланируем их если нужно
        for future_job_id, future_duration in future_jobs:
            # Получаем текущие параметры работы
            cursor.execute(
                "SELECT start_date, hour_offset FROM jobs WHERE id = ?",
                (future_job_id,)
            )
            result = cursor.fetchone()
            if not result:
                continue

            current_start_date, current_offset = result
            current_offset = current_offset or 0.0

            # Если работа начинается после next_start_date - выходим из цикла
            current_start_dt = datetime.fromisoformat(current_start_date) + timedelta(hours=current_offset)
            if current_start_dt >= next_start_dt:
                break

            # Перепланируем работу на next_start_date
            cursor.execute(
                "UPDATE jobs SET start_date = ?, hour_offset = ? WHERE id = ?",
                (next_start_date, next_start_offset, future_job_id)
            )

            # Вычисляем новые параметры финиша для перепланированной работы
            new_finish_date, new_daily_schedule = calculate_finish_date(
                conn, next_start_date, future_duration, next_start_offset,
                future_job_id
            )

            # Обновляем next_start_date для следующей работы
            if new_daily_schedule:
                last_day_date, last_day_hours, last_day_offset = new_daily_schedule[-1]
                new_finish_offset = last_day_offset + last_day_hours
            else:
                new_finish_offset = 0

            new_finish_dt = datetime.fromisoformat(new_finish_date)
            next_start_dt = new_finish_dt + timedelta(hours=new_finish_offset + 0.25)
            next_start_date = next_start_dt.date().isoformat()
            next_start_offset = next_start_dt.hour + next_start_dt.minute / 60.0

        # Фиксируем изменения в БД
        conn.commit()

    # 7. Возвращаем исходные доступные дату и смещение
    return True


def get_future_jobs_excluding_current_optimized(conn, need_date: str, offset: float, exclude_job_id: Optional[int],
                                                equipment_id: int) -> List[Tuple[int, float]]:
    """
    Оптимизированная версия - возвращает только ID работы и длительность.
    """
    cursor = conn.cursor()

    # Базовый запрос
    query = '''
        SELECT id, start_date, duration_hours, hour_offset
        FROM jobs 
        WHERE equipment_id = ? 
          AND status IN ('planned', 'started')
    '''

    params = [equipment_id]

    # Добавляем условие исключения если нужно
    if exclude_job_id is not None:
        query += ' AND id != ?'
        params.append(exclude_job_id)

    query += ' ORDER BY start_date, hour_offset'

    cursor.execute(query, params)
    jobs = cursor.fetchall()
    future_jobs = []

    need_date_dt = datetime.fromisoformat(need_date).date()

    for job in jobs:
        job_id, start_date, duration_hours, hour_offset = job
        hour_offset = hour_offset or 0.0

        # Рассчитываем дату завершения работы
        finish_date_str, daily_schedule = calculate_finish_date(
            conn, start_date, duration_hours, hour_offset, job_id
        )
        finish_date = datetime.fromisoformat(finish_date_str).date()
        _, last_day_hours, last_day_offset = daily_schedule[-1]
        # Проверяем, что работа завершается после need_date
        if finish_date > need_date_dt or (finish_date == need_date_dt and offset < last_day_offset + last_day_hours):
            future_jobs.append((job_id, duration_hours))

    return future_jobs


def get_work_hours_for_date(conn, date_str: str) -> int:
    cursor = conn.cursor()
    cursor.execute('SELECT work_hours FROM calendar WHERE date=?', (date_str,))
    result = cursor.fetchone()
    return result[0] if result else 8


def ensure_working_day(conn, date_str: str) -> str:
    """
    Гарантированно возвращает рабочую дату.
    Если указанная дата - выходной, возвращает первый рабочий день после нее.
    Если день рабочий, возвращает ту же дату.
    """
    cursor = conn.cursor()

    # Проверяем, является ли указанная дата выходным
    cursor.execute('SELECT work_hours FROM calendar WHERE date=?', (date_str,))
    result = cursor.fetchone()

    # Если записи нет в календаре, считаем стандартным рабочим днем
    if result is None:
        return date_str

    work_hours = result[0]

    # Если день рабочий, возвращаем ту же дату
    if work_hours > 0:
        return date_str

    # Если день выходной, ищем следующий рабочий день
    current_date = datetime.fromisoformat(date_str).date()
    max_attempts = 30

    for attempt in range(max_attempts):
        current_date += timedelta(days=1)
        next_date_str = current_date.isoformat()

        cursor.execute('SELECT work_hours FROM calendar WHERE date=?', (next_date_str,))
        result = cursor.fetchone()

        # Если записи нет в календаре, считаем стандартным рабочим днем
        if result is None:
            return next_date_str

        work_hours = result[0]
        if work_hours > 0:
            return next_date_str

    return current_date.isoformat()


def calculate_finish_date(conn, start_date_str: Optional[str] = None, duration_hours: Optional[float] = None,
                          hour_offset: Optional[float] = None,
                          job_id: Optional[int] = None) -> Tuple[str, List[Tuple[str, float, float]]]:
    """
    Расчет даты завершения работы с разбивкой по дням.
    Если передан job_id - берет параметры из базы данных.
    Если job_id не передан - использует переданные параметры.
    Возвращает: (finish_date, список дней с занятыми часами и смещением)
    """

    # Если передан job_id, загружаем параметры из базы
    if job_id is not None:
        cursor = conn.cursor()
        cursor.execute('''
            SELECT start_date, duration_hours, hour_offset, equipment_id
            FROM jobs 
            WHERE id = ?
        ''', (job_id,))

        result = cursor.fetchone()
        if not result:
            raise ValueError(f"Работа с ID {job_id} не найдена")

        start_date_str, duration_hours, hour_offset, equipment_id = result
        hour_offset = hour_offset or 0.0
    else:
        # Проверяем, что все необходимые параметры переданы
        if start_date_str is None or duration_hours is None or hour_offset is None:
            raise ValueError(
                "При job_id=None необходимо передать start_date_str, duration_hours, hour_offset и equipment_id")

        hour_offset = hour_offset or 0.0

    start_date = datetime.fromisoformat(start_date_str).date()
    remaining_hours = duration_hours
    current_date = start_date
    daily_schedule = []
    current_offset = hour_offset

    # Распределяем часы работы по дням
    first_day = True
    while remaining_hours > 0:
        date_str = current_date.isoformat()
        work_hours = get_work_hours_for_date(conn, date_str)

        if work_hours > 0:  # Рабочий день
            # Получаем текущую загрузку оборудования на этот день
            available_hours = work_hours

            if first_day:
                available_hours -= current_offset
                first_day = False

            if available_hours > 0:
                hours_today = min(available_hours, remaining_hours)
                daily_schedule.append((date_str, hours_today, current_offset))
                remaining_hours -= hours_today
                current_offset = 0

        if remaining_hours > 0:
            current_date += timedelta(days=1)

    return current_date.isoformat(), daily_schedule


def check_equipment_conflicts(conn, equipment_id: int, job_id: int, start_date_str: str, hour_offset: float,
                              duration_hours: float) -> tuple[str, float]:
    """
    Проверяет конфликты на оборудовании и возвращает доступную дату старта.
    Если есть конфликты, находит следующую доступную дату.
    """

    def adjust_date_for_work_hours(date_str: str, offset: float) -> tuple[str, float]:
        """Корректирует дату и смещение с учетом рабочих часов"""
        work_hours = get_work_hours_for_date(conn, date_str)

        # Если день выходной, ищем следующий рабочий день
        if work_hours == 0:
            next_working_day = ensure_working_day(conn, date_str)
            return next_working_day, 0.0  # Начинаем с начала рабочего дня

        # Если смещение превышает рабочий день, переходим к следующему дню
        if offset >= work_hours:
            next_date = (datetime.fromisoformat(date_str) + timedelta(days=1)).date().isoformat()
            next_work_hours = get_work_hours_for_date(conn, next_date)

            # Если следующий день выходной, ищем рабочий
            if next_work_hours == 0:
                next_working_day = ensure_working_day(conn, next_date)
                return next_working_day, 0.0

            # Корректируем смещение для следующего дня
            adjusted_offset = offset - work_hours
            return next_date, adjusted_offset

        return date_str, offset

    def get_job_time_range_with_calendar(job_start: str, job_duration: float, job_offset: float,
                                         exclude_job_id: int = None) -> tuple[datetime, datetime]:
        """Рассчитывает временной диапазон работы с учетом календаря и оборудования"""
        # Используем готовую функцию calculate_finish_date
        finish_date, daily_schedule = calculate_finish_date(conn, job_start, job_duration, job_offset,
                                                            exclude_job_id)

        # Начало работы с учетом смещения
        start_dt = datetime.fromisoformat(job_start)
        start_with_offset = start_dt + timedelta(hours=job_offset)

        # Конец работы - дата из calculate_finish_date + время окончания в последний день
        last_day_schedule = daily_schedule[-1] if daily_schedule else (finish_date, 0, 0)
        last_day_date = datetime.fromisoformat(last_day_schedule[0])
        last_day_hours = last_day_schedule[1]
        last_day_offset = last_day_schedule[2] if len(last_day_schedule) > 2 else 0

        # Время окончания в последний день
        end_dt = last_day_date + timedelta(hours=last_day_offset + last_day_hours)

        return start_with_offset, end_dt

    def has_time_conflict(test_start_dt: datetime, test_end_dt: datetime, conflict_start_dt: datetime, conflict_end_dt: datetime) -> bool:
        """Проверяет пересечение временных интервалов"""
        return conflict_start_dt <= test_start_dt < conflict_end_dt or \
            conflict_start_dt < test_end_dt <= conflict_end_dt or \
            (test_start_dt <= conflict_start_dt and test_end_dt >= conflict_end_dt)

    # Начинаем с исходной даты
    current_date = start_date_str
    current_offset = hour_offset
    max_iterations = 100  # Защита от бесконечного цикла

    for iteration in range(max_iterations):
        # Корректируем дату и смещение с учетом рабочих часов
        adjusted_date, adjusted_offset = adjust_date_for_work_hours(current_date, current_offset)

        # Получаем временной диапазон для проверяемой работы с учетом календаря
        test_start_dt, test_end_dt = get_job_time_range_with_calendar(
            adjusted_date, duration_hours, adjusted_offset, job_id
        )

        # Получаем все работы на оборудовании (кроме текущей)
        cursor = conn.cursor()
        if job_id:
            cursor.execute('''
                SELECT id, start_date, duration_hours, hour_offset, is_locked
                FROM jobs 
                WHERE equipment_id=? AND id!=? AND status IN ('planned', 'started')
                ORDER BY start_date
            ''', (equipment_id, job_id))
        else:
            cursor.execute('''
                SELECT id, start_date, duration_hours, hour_offset, is_locked
                FROM jobs 
                WHERE equipment_id=? AND status IN ('planned', 'started')
                ORDER BY start_date
            ''', (equipment_id,))

        existing_jobs = cursor.fetchall()
        has_conflict = False

        for job in existing_jobs:
            job_db_id, job_start, job_duration, job_offset, job_locked = job
            job_offset = job_offset or 0

            # Получаем временной диапазон существующей работы с учетом календаря
            conflict_start_dt, conflict_end_dt = get_job_time_range_with_calendar(
                job_start, job_duration, job_offset, job_db_id
            )

            # Проверяем конфликт
            if has_time_conflict(test_start_dt,test_end_dt, conflict_start_dt, conflict_end_dt):
                has_conflict = True

                # Начинаем после окончания конфликтующей работы + 0.25 часа
                new_start_dt = conflict_end_dt + timedelta(hours=0.25)

                # Обновляем текущую дату и смещение
                current_date = new_start_dt.date().isoformat()
                current_offset = new_start_dt.hour + new_start_dt.minute / 60.0
                break

        # Если конфликтов нет, возвращаем текущую дату
        if not has_conflict:
            return adjusted_date, adjusted_offset

        # Если прошли все итерации, возвращаем последнюю проверенную дату
        if iteration == max_iterations - 1:
            return adjusted_date, adjusted_offset

    return adjusted_date, adjusted_offset


# Получение следующего свободного порядкового номера
def get_next_sort_order(conn, table_name: str) -> int:
    cursor = conn.cursor()
    cursor.execute(f'SELECT MAX(sort_order) FROM {table_name}')
    result = cursor.fetchone()
    return (result[0] or 0) + 1


# Проверка уникальности порядкового номера
def is_sort_order_unique(conn, table_name: str, sort_order: int, exclude_id: int = None) -> bool:
    cursor = conn.cursor()
    if exclude_id:
        cursor.execute(f'SELECT COUNT(*) FROM {table_name} WHERE sort_order=? AND id!=?', (sort_order, exclude_id))
    else:
        cursor.execute(f'SELECT COUNT(*) FROM {table_name} WHERE sort_order=?', (sort_order,))
    return cursor.fetchone()[0] == 0


