def get_equipment_name(conn, equipment_id: int) -> str:
    """Получает название оборудования по ID"""
    cursor = conn.cursor()
    cursor.execute("SELECT name FROM equipment WHERE id = ?", (equipment_id,))
    result = cursor.fetchone()
    return result[0] if result else "Неизвестное оборудование"


def move_order_up(conn, order_id):
    """Перемещает заказ на одну позицию вверх"""
    cursor = conn.cursor()

    # Получаем все заказы в текущем порядке
    cursor.execute("SELECT id, priority_order FROM orders ORDER BY priority_order")
    orders = cursor.fetchall()

    # Находим индекс текущего заказа
    current_index = None
    for i, (oid, _) in enumerate(orders):
        if oid == order_id:
            current_index = i
            break

    if current_index is None or current_index == 0:
        return

    # Получаем ID заказов для обмена
    current_order_id = orders[current_index][0]
    previous_order_id = orders[current_index - 1][0]

    # Просто меняем priority_order местами
    cursor.execute("UPDATE orders SET priority_order = priority_order + 1 WHERE id = ?", (previous_order_id,))
    cursor.execute("UPDATE orders SET priority_order = priority_order - 1 WHERE id = ?", (current_order_id,))

    conn.commit()


def move_order_down(conn, order_id):
    """Перемещает заказ на одну позицию вниз"""
    cursor = conn.cursor()

    # Получаем все заказы в текущем порядке
    cursor.execute("SELECT id, priority_order FROM orders ORDER BY priority_order")
    orders = cursor.fetchall()

    # Находим индекс текущего заказа
    current_index = None
    for i, (oid, _) in enumerate(orders):
        if oid == order_id:
            current_index = i
            break

    if current_index is None or current_index == len(orders) - 1:
        return

    # Получаем ID заказов для обмена
    current_order_id = orders[current_index][0]
    next_order_id = orders[current_index + 1][0]

    # Просто меняем priority_order местами
    cursor.execute("UPDATE orders SET priority_order = priority_order - 1 WHERE id = ?", (next_order_id,))
    cursor.execute("UPDATE orders SET priority_order = priority_order + 1 WHERE id = ?", (current_order_id,))

    conn.commit()


def recalculate_priority_order(conn):
    """Пересчитывает порядок приоритетов после удаления заказа"""
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM orders ORDER BY priority_order")
    orders = cursor.fetchall()

    for i, (order_id,) in enumerate(orders):
        cursor.execute("UPDATE orders SET priority_order = ? WHERE id = ?", (i + 1, order_id))

    conn.commit()

def load_fonts_for_deployment():
    """Функция для загрузки шрифтов в deployment среде"""
    # Пробуем загрузить из папки fonts
    font_path = "./fonts/arial.ttf"
    boldfont_path = "./fonts/arialbd.ttf"
    if os.path.exists(font_path):
        return {
            'small': ImageFont.truetype(font_path, 10),
            'medium': ImageFont.truetype(font_path, 12),
            'large': ImageFont.truetype(boldfont_path, 14)
        }


