                # shadow_color = (111, 111, 111, 64)  # Полупрозрачная черная тень
                # draw.rectangle([x_start + 2, y_top + 2, x_finish + 2, y_bottom + 2],
                #                fill=shadow_color)
                outline_color = lighten_color(color, 0.7)
                draw_rounded_rectangle(draw,
                                       [x_start, y_top, x_finish, y_bottom],
                                       radius=3,  # Радиус скругления
                                       fill=color,
                                       outline=outline_color,
                                       width=4
                                       )
                # draw.rectangle([x_start, y_top, x_finish, y_bottom],
                #                fill=color, outline='black', width=1)

                # НОВОЕ: Визуальное обозначение выходных дней внутри работы
